"use strict";

const https = require("node:https");

function readText(res) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    res.setEncoding("utf8");
    res.on("data", (chunk) => chunks.push(chunk));
    res.on("end", () => resolve(chunks.join("")));
    res.on("error", reject);
  });
}

exports.post = function post(url, body) {
  return new Promise((resolve, reject) => {
    const agent = new https.Agent({ keepAlive: true, maxSockets: 3, maxFreeSockets: 1 });
    let sameAgent = false;
    const req = https.request(url, {
      method: "POST",
      headers: {
        "content-type": "text/plain",
        "x-fixture": "https-request-client",
      },
      agent,
      timeout: 1000,
    }, async (res) => {
      try {
        const text = await readText(res);
        agent.destroy();
        resolve([
          "httpnpm.https-request=" + res.statusCode,
          res.statusMessage,
          res.headers["x-method"],
          res.headers["x-path"],
          text,
          "agent=" + sameAgent,
        ].join("|"));
      } catch (error) {
        agent.destroy();
        reject(error);
      }
    });
    sameAgent = req.agent === agent;
    req.on("error", (error) => {
      agent.destroy();
      reject(error);
    });
    req.end(body);
  });
};
